INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('swami-ramsukhdas-hc:source:8.3','Swami Ramsukhdas','gita.8.3','hi','commentary','।।8.3।। व्याख्या--''अक्षरं ब्रह्म परमम्''--परम अक्षरका नाम ब्रह्म है। यद्यपि गीतामें ब्रह्म शब्द प्रणव वेद प्रकृति आदिका वाचक भी आया है तथापि यहाँ ब्रह्म शब्दके साथ परम और अक्षर विशेषण देनेसे यह शब्द सर्वोपरि सच्चिदानन्दघन अविनाशी निर्गुणनिराकार परमात्माका वाचक है।''स्वभावोऽध्यात्ममुच्यते''--अपने भाव अर्थात् होनेपनका नाम स्वभाव है --''स्वो भावः स्वभावः''। इसी स्वभावको अध्यात्म कहा जाता है अर्थात् जीवमात्रके होनेपनका नाम अध्यात्म है।
ऐसे तो आत्माको लेकर जो वर्णन किया जाता है वह भी अध्यात्म है अध्यात्ममार्गका जिसमें वर्णन हो वह मार्ग भी अध्यात्म है और इस आत्माकी जो विद्या है उसका नाम भी अध्यात्म है (गीता 10। 32)। परन्तु यहाँ स्वभाव विशेषणके साथ अध्यात्म शब्द आत्माका अर्थात् जीवके होनेपन का (स्वरूपका) वाचक है। ''भूतभावोद्भवकरो विसर्गः कर्मसंज्ञितः''-- स्थावरजङ्गम जितने भी प्राणी देखनेमें आते हैं उनका जो भाव अर्थात् होनापन है उस होनेपनको प्रकट करनेके लिये जो विसर्ग अर्थात् त्याग है उसको कर्म कहते हैं।महाप्रलयके समय प्रकृतिकी अक्रियअवस्था मानी जाती है तथा महासर्गके समय प्रकृतिकीसक्रिय अवस्था मानी जाती है। इस सक्रियअवस्थाका कारण भगवान्का संकल्प है कि मैं एक ही बहुत रूपोंसे हो जाऊँ। इसी संकल्पसे सृष्टिकी रचना होती है। तात्पर्य है कि महाप्रलयके समय अहंकार और सञ्चित कर्मोंके सहित प्राणी प्रकृतिमें लीन हो जाते हैं और उन प्राणियोंके सहित प्रकृति एक तरहसे परमात्मामें लीन हो जाती है। उस लीन हुई प्रकृतिको विशेष क्रियाशील करनेके लिये भगवान्का पूर्वोक्त संकल्प ही विसर्ग अर्थात्,त्याग है। भगवान्का यह संकल्प ही कर्मोंका आरम्भ है जिससे प्राणियोंकी कर्मपरम्परा चल पड़ती है। कारण कि महाप्रलयमें प्राणियोंके कर्म नहीं बनते प्रत्युत उसमें प्राणियोंकी सुषुप्तअवस्था रहती है। महासर्गके आदिसे कर्म शुरू हो जाते हैं।
चौदहवें अध्यायमें आया है -- परमात्माकी मूल प्रकृतिका नाम महद्ब्रह्म है। उस प्रकृतिमें लीन हुए जीवोंका प्रकृतिके साथ विशेष सम्बन्ध करा देना अर्थात् जीवोंका अपनेअपने कर्मोंके फलस्वरूप शरीरोंके साथ सम्बन्ध करा देना ही परमात्माके द्वारा प्रकृतिमें गर्भस्थापन करना है (गीता 14। 3 4)। उसमें भी अलगअलग योनियोंमें तरहतरहके जितने शरीर पैदा होते हैं उन शरीरोंकी उत्पत्तिमें प्रकृति हेतु है और उनमें जीवरूपसे भगवान्का अंश है -- ''ममैवांशो जीवलोके'' (गीता 15। 7)। इस प्रकार प्रकृति और पुरुषके अंशसे सम्पूर्ण प्राणी पैदा होते हैं।
तेरहवें अध्यायके छब्बीसवें श्लोकमें भगवान्ने कहा है कि स्थावरजङ्गम जितने भी प्राणी उत्पन्न होते हैं वे सब क्षेत्र (प्रकृति) और क्षेत्रज्ञ(पुरुष) के संयोगसे ही होते हैं। क्षेत्रक्षेत्रज्ञका विशेष संयोग अर्थात् स्थूलशरीर धारण करानेके लिये भगवान्का संकल्परूप विशेष सम्बन्ध ही स्थावरजङ्गम प्राणियोंके स्थूलशरीर पैदा करनेका कारण है। उस संकल्पके होनेमें भगवान्का कोई अभिमान नहीं है प्रत्युत जीवोंके जन्मजन्मान्तरोंके जो कर्मसंस्कार हैं वे महाप्रलयके समय परिपक्व होकर जब फल देनेके लिये उन्मुख होते हैं तब भगवान्का संकल्प होता है (टिप्पणी प0 450)। इस प्रकार जीवोंके कर्मोंकी प्रेरणासे भगवान्में मैं एक ही बहुत रूपोंसे हो जाऊँ -- यह संकल्प होता है।मनुष्यमात्रके द्वारा विहित और निषिद्ध जितनी क्रियाएँ होती हैं उन सब क्रियाओंका नाम कर्म है। तात्पर्य है कि मुख्य कर्म तो भगवान्का संकल्प हुआ और उसके बाद कर्मपरम्परा चलती है।'),
('swami-ramsukhdas-hc:source:8.4','Swami Ramsukhdas','gita.8.4','hi','commentary','।।8.4।। व्याख्या --''अधिभूतं क्षरो भावः''--पृथ्वी जल तेज वायु और आकाश -- इन पञ्चमहाभूतोंसे बनी प्रतिक्षण परिवर्तनशील और नाशवान् सृष्टिको अधिभूत कहते हैं।''पुरुषश्चाधिदैवतम्''-- यहाँ ''अधिदैवत'' (अधिदैव) पद आदिपुरुष हिरण्यगर्भ ब्रह्माका वाचक है। महासर्गके आदिमें भगवान्के संकल्पसे सबसे पहले ब्रह्माजी ही प्रकट होते हैं और फिर वे ही सर्गके आदिमें सब सृष्टिकी रचना करते हैं।
''अधियज्ञोऽहमेवात्र देहे देहभृतां वर''--हे देहधारियोंमें श्रेष्ठ अर्जुन इस देहमें अधियज्ञ मैं ही हूँ अर्थात् इस मनुष्यशरीरमें अन्तर्यामीरूपसे मैं ही हूँ (टिप्पणी प0 451.1)। भगवान्ने गीतामें ''हृदि सर्वस्य विष्ठितम्'' (13। 17) ''सर्वस्य चाहं हृदि संनिविष्टः'' (15। 15) ''ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति'' (18। 61) आदिमें अपनेको अन्तर्यामीरूपसे सबके हृदयमें विराजमान बताया है।
''अहमेव अत्र (टिप्पणी प0 451.2) देहे''कहनेका तात्पर्य है कि दूसरी योनियोंमें तो पूर्वकृत कर्मोंका भोग होता है नये कर्म नहीं बनते पर इस मनुष्यशरीरमें नये कर्म भी बनते हैं। उन कर्मोंके प्रेरक अन्तर्यामी भगवान् होते हैं (टिप्पणी प0 451.3)। जहाँ मनुष्य रागद्वेष नहीं करता उसके सब कर्म भगवान्की प्रेरणाके अनुसार शुद्ध होते हैं अर्थात् बन्धनकारक नहीं होते और जहाँ वह रागद्वेषके कारण भगवान्की प्रेरणाके अनुसार कर्म नहीं करता उसके कर्म बन्धनकारक होते हैं। कारण कि राग और द्वेष मनुष्यके महान् शत्रु हैं (गीता 3। 34)। तात्पर्य यह हुआ कि भगवान्की प्रेरणासे कभी निषिद्धकर्म होते ही नहीं। श्रुति और स्मृति भगवान्की आज्ञा है -- ''श्रुतिस्मृती ममैवाज्ञे।'' अतः भगवान् श्रुति और स्मृतिके विरुद्ध प्रेरणा कैसे कर सकते हैं नहीं कर सकते। निषिद्धकर्म तो मनुष्य कामनाके वशीभूत होकर ही करता है (गीता 3। 37)। अगर मनुष्य कामनाके वशीभूत न हो तो उसके द्वारा स्वाभाविक ही विहित कर्म होंगे जिनको अठारहवें सहज,स्वभावनियत कर्म नामसे कहा गया है।यहाँ अर्जुनके लिये ''देहभृतां वर'' कहनेका तात्पर्य है कि देहधारियोंमें वही मनुष्य श्रेष्ठ है जो इस देहमें परमात्मा हैं -- ऐसा जान लेता है। ऐसा ज्ञान न हो तो भी ऐसा मान ले कि स्थूल सूक्ष्म और कारणशरीरके कणकणमें परमात्मा हैं और उनका अनुभव करना ही मनुष्यजन्मका खास ध्येय है। इस ध्येयकी सिद्धिके लिये परमात्माकी आज्ञाके अनुसार ही काम करना है।तीसरे और चौथे श्लोकमें जो ब्रह्म अध्यात्म कर्म अधिभूत अधिदैव और अधियज्ञका वर्णन हुआ है उसे समझनेमात्रके लिये जलका एक दृष्टान्त दिया जाता है। जैसे जब आकाश स्वच्छ होता है तब हमारे और सूर्यके मध्यमें कोई पदार्थ न दीखनेपर भी वास्तवमें वहाँ परमाणुरूपसे जलतत्त्व रहता है। वही जलतत्त्व भाप बनता है और भापके घनीभूत होनेपर बादल बनता है। बादलमें जो जलकण रहते हैं उनके मिलनेसे बूँदें बन जाती हैं। उन बूँदोंमें जब ठण्डकके संयोगसे घनता आ जाती है तब वे ही बूँदें ओले (बर्फ) बन जाती हैं -- यह जलतत्त्वका बहुत स्थूल रूप हुआ। ऐसे ही निर्गुणनिराकार ब्रह्म परमाणुरूपसे जलतत्त्व है अधियज्ञ (व्यापक विष्णु) भापरूपसे जल है अधिदैव (हिरण्यगर्भ ब्रह्मा) बादलरूपसे जल है अध्यात्म (अनन्त जीव) बूँदेंरूपसे जल है कर्म (सृष्टिरचनारूप कर्म) वर्षाकी क्रिया है और,अधिभूत (भौतिक सृष्टिमात्र) बर्फरूपसे जल है।
इस वर्णनका तात्पर्य यह हुआ कि जैसे एक ही जल परमाणु भाप बादल वर्षाकी क्रिया बूँदें और ओले(बर्फ) के रूपसे भिन्नभिन्न दीखता है पर वास्तवमें है एक ही। इसी प्रकार एक ही परमात्मतत्त्व ब्रह्म अध्यात्म कर्म अधिभूत अधिदैव और अधियज्ञके रूपसे भिन्नभिन्न प्रतीत होते हुए भी तत्त्वतः एक ही है। इसीको सातवें अध्यायमें ''समग्रम्'' (7। 1) और ''वासुदेवः सर्वम्'' (7। 19) कहा गया है।
तात्त्विक दृष्टिसे तो सब कुछ वासुदेव ही है (7। 19)। इसमें भी जब विवेकदृष्टिसे देखते हैं तब शरीरशरीरी प्रकृतिपुरुष -- ऐसे दो भेद हो जाते हैं। उपासनाकी दृष्टिसे देखते हैं तो उपास्य (परमात्मा) उपासक (जीव) और त्याज्य (प्रकृतिका कार्य -- संसार) -- ये तीन भेद हो जाते हैं। इन तीनोंको समझनेके लिये यहाँ इनके छः भेद किये गये हैं -- परमात्माके दो भेद -- ब्रह्म (निर्गुण) और अधियज्ञ (सगुण)।जीवके दो भेद -- अध्यात्म (सामान्य जीव जो कि बद्ध हैं) और अधिदैव (कारक पुरुष जो कि मुक्त हैं)।संसारके दो भेद -- कर्म (जो कि परिवर्तनका पुञ्ज है) और अधिभूत (जो कि पदार्थ हैं)।
1. ब्रह्म
2. अध्यात्म
3. कर्म
4. अधिभूत
5. अधिदैव
6. अधियज्ञ
विशेष बात
(1)सब संसारमें परमात्मा व्याप्त हैं --''मया ततमिदं सर्वम्'' (9। 4) ''येन सर्वमिदं ततम्'' (18। 46) सब संसार परमात्मामें है -- ''मयि सर्वमिदं प्रोतम्'' (7। 7) सब कुछ परमात्मा ही हैं --''वासुदेवः सर्वम्'' (7। 19) सब संसार परमात्माका है--''अहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च'' (9। 24) ''भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम्'' (5। 29) -- इस प्रकार गीतामें भगवान्के तरहतरहके वचन आते हैं। इन सबका सामञ्जस्य कैसे हो सबकी संगति कैसे बैठे इसपर विचार किया जाता है।
संसारमें परमात्मप्राप्तिके लिये अपने कल्याणके लिये साधना करनेवाले जितने भी साधक (टिप्पणी प0 452) हैं वे सभी संसारसे छूटना चाहते हैं और परमात्माको प्राप्त करना चाहते हैं। कारण कि संसारके साथ सम्बन्ध रखनेसे सदा रहनेवाली शान्ति और सुख नहीं मिल सकता प्रत्युत सदा अशान्ति और दुःख ही मिलता रहता है -- ऐसा मनुष्योंका प्रत्यक्ष अनुभव है। परमात्मा अनन्त आनन्दके स्वरूप हैं वहाँ दुःखका लेश भी नहीं है -- ऐसा शास्त्रोंका कथन है और सन्तोंका अनुभव है।अब विचार यह करना है कि साधकको संसार तो प्रत्यक्षरूपसे दीखता है और परमात्माको वह केवल मानता है क्योंकि परमात्मा प्रत्यक्ष दीखते नहीं। शास्त्र और सन्त कहते हैं कि संसारमें परमात्मा हैं और परमात्मामें संसार है इसको मानकर साधक साधन करता है। उस साधनामें जबतक संसारकी मुख्यता रहती है तबतक परमात्माकी मान्यता गौण रहती है। साधन करतेकरते ज्योंज्यों परमात्माकी धारणा (मान्यता) मुख्य होती चली जाती है त्योंहीत्यों संसारकी मान्यता गौण होती चली जाती है। परमात्माकी धारणा सर्वथा मुख्य होनेपर साधकको यह स्पष्ट दीखने लग जाता है कि संसार पहले नहीं था और फिर बादमें नहीं रहेगा तथा वर्तमानमें जो है रूपसे दीखता है वह भी प्रतिक्षण अभावमें जा रहा है। जब संसार नहीं था तब भी परमात्मा थे जब संसार नहीं रहेगा तब भी परमात्मा रहेंगे और वर्तमानमें संसारके प्रतिक्षण अभावमें जाते हुए भी परमात्मा ज्योंकेत्यों विद्यमान हैं। तात्पर्य है कि संसारका सदा अभाव है और परमात्माका सदा भाव है। इस तरह जब संसारकी स्वतन्त्र सत्ताका सर्वथा अभाव हो जाता है तब सत्यस्वरूपसे सब कुछ परमात्मा ही हैं -- ऐसा वास्तविक अनुभव हो जाता है जिसके होनेसे साधक सिद्ध कहा जाता है। कारण कि संसारमें परमात्मा हैं और परमात्मामें संसार है -- ऐसी मान्यता संसारकी सत्ता माननेसे ही होती थी और संसारकी सत्ता साधकके रागके कारण ही दीखती थी। तत्त्वतः सब कुछ परमात्मा ही हैं।
(2)सत् और असत् सब परमात्मा ही हैं --''सदसच्चाहम्'' (9। 19) परमात्मा न सत् कहे जा सकते हैं और न असत् कहे जा सकते हैं -- ''न सत्तन्नासदुच्यते'' (13। 12) परमात्मा सत् भी हैं असत् भी हैं और सत्असत् दोनोंसे परे भी हैं --''सदसत्तत्परं यत्'' (11। 37)। इस प्रकार गीतामें भिन्नभिन्न वचन आते हैं। अब उनकी संगतिके विषयमें विचार किया जाता है।परमात्मतत्त्व अत्यन्त अलौकिक और विलक्षण है। उस तत्त्वका वर्णन कोई भी नहीं कर सकता। उस तत्त्वको इन्द्रियाँ मन और बुद्धि नहीं पकड़ सकते अर्थात् वह तत्त्व इन्द्रियाँ मन और बुद्धिकी परिधिमें नहीं आता। हाँ इन्द्रियाँ मन और बुद्धि उसमें विलीन हो सकते हैं। साधक उस तत्त्वमें स्वयं लीन हो सकता है उसको प्राप्त कर सकता है पर उस तत्त्वको अपने कब्जेमें अपने अधिकारमें अपनी सीमामें नहीं ले सकता।परमात्मतत्त्वकी प्राप्ति चाहनेवाले साधक दो तरहके होते हैं -- एक विवेकप्रधान और एक श्रद्धाप्रधान अर्थात् एक मस्तिष्कप्रधान होता है और एक हृदयप्रधान होता है। विवेकप्रधान साधकके भीतर विवेककी अर्थात् जाननेकी मुख्यता रहती है और श्रद्धाप्रधान साधकके भीतर माननेकी मुख्यता रहती है। इसका तात्पर्य यह नहीं है कि विवेकप्रधान साधकमें श्रद्धा नहीं रहती और श्रद्धाप्रधान साधकमें विवेक नहीं रहता प्रत्युत यह तात्पर्य है कि विवेकप्रधान साधकमें विवेककी मुख्यता और साथमें श्रद्धा रहती है तथा श्रद्धाप्रधान साधकमें श्रद्धाकी मुख्यता और साथमें विवेक रहता है। दूसरे शब्दोंमें जाननेवालोंमें मानना भी रहता है और माननेवालोंमें जानना भी रहता है। जाननेवाले जानकर मान लेते हैं और माननेवाले मानकर जान लेते हैं। अतः किसी भी तरहके साधकमें किञ्चिन्मात्र भी कमी नहीं रहती।साधक चाहे विवेकप्रधान हो चाहे श्रद्धाप्रधान हो पर साधनमें उसकी अपनी रुचि श्रद्धा विश्वास और योग्यताकी प्रधानता रहती है। रुचि श्रद्धा विश्वास और योग्यता एक साधनमें होनेसे साधक उस तत्त्वको जल्दी समझता है। परन्तु रुचि और श्रद्धाविश्वास होनेपर भी वैसी योग्यता न हो अथवा योग्यता होनेपर भी वैसी रुचि और श्रद्धाविश्वास न हो तो साधकको उस साधनमें कठिनता पड़ती है। रुचि होनेसे मन स्वाभाविक लग जाता है श्रद्धाविश्वास होनेसे बुद्धि स्वाभाविक लग जाती है और योग्यता होनेसे बात ठीक समझमें आ जाती है।विवेकप्रधान साधक निर्गुणनिराकारको पसंद करता है अर्थात् उसकी रुचि निर्गुणनिराकारमें होती है। श्रद्धाप्रधान साधक सगुणसाकारको पसंद करता है अर्थात् उसकी रुचि सगुणसाकारमें होती है। जो निर्गुणनिराकारको पसंद करता है वह यह कहता है कि परमात्मतत्त्व न सत् कहा जा सकता है और न असत् कहा जा सकता है। जो सगुणसाकारको पसंद करता है तो वह कहता है कि परमात्मा सत् भी हैं असत् भी हैं और सत्असत्से परे भी हैं।तात्पर्य यह हुआ कि चिन्मयतत्त्व तो हरदम ज्योंकात्यों ही रहता है और जड असत् कहलानेवाला संसार निरन्तर बदलता रहता है। जब यह चेतन जीव बदलते हुए संसारको महत्त्व देता है उसके साथ सम्बन्ध जोड़ लेता है तब यह जन्ममरणके चक्करमें घूमता रहता है। परन्तु जब यह जडतासे सर्वथा सम्बन्धविच्छेद कर लेता है तब इसको स्वतःसिद्ध चिन्मयतत्त्वका अनुभव हो जाता है। विवेकप्रधान साधक विवेकविचारके द्वारा जडताका त्याग करता है। जडताका त्याग होनेपर चिन्मयतत्त्व अवशेष रहता है अर्थात् नित्यप्राप्त तत्त्वका अनुभव हो जाता है। श्रद्धाप्रधान साधक केवल भगवान्के ही सम्मुख हो जाता है जिससे वह जडतासे विमुख होकर भगवान्को प्रेमपूर्वक प्राप्त कर लेता है। विवेकप्रधान साधक तो सम शान्त सत्घन चित्घन आनन्दघन तत्त्वमें अटल स्थित होकर अखण्ड आनन्दको प्राप्त होता है पर श्रद्धाप्रधान साधक भगवान्के साथ अभिन्न होकर प्रेमके अनन्त प्रतिक्षण वर्धमान आनन्दको प्राप्त कर लेता है।इस प्रकार दोनों ही साधकोंको जडतासे सर्वथा सम्बन्धविच्छेदपूर्वक चिन्मयतत्त्वकी प्राप्ति हो जाती है और,सत्असत् अर्थात् सब कुछ परमात्मा ही हैं -- ऐसा अनुभव हो जाता है।
सम्बन्ध --दूसरे श्लोकमें अर्जुनका सातवाँ प्रश्न था कि अन्तकालमें आप कै'),
('swami-ramsukhdas-hc:source:8.4','Swami Ramsukhdas','gita.8.4','hi','commentary','से जाननेमें आते हैं इसका उत्तर भगवान् आगेके श्लोकमें देते हैं।'),
('swami-ramsukhdas-hc:source:8.5','Swami Ramsukhdas','gita.8.5','hi','commentary','।।8.5।। व्याख्या--''अन्तकाले च'' ''मामेव ৷৷. याति नास्त्यत्र संशयः''-- अन्तकालमें भी मेरा स्मरण करते हुए जो शरीर छोड़कर जाता है -- इसका तात्पर्य हुआ कि इस मनुष्यको जीवनमें साधनभजन करके अपना उद्धार करनेका अवसर दिया था पर इसने कुछ किया ही नहीं। अब बेचारा यह मनुष्य अन्तकालमें दूसरा साधन करनेमें असमर्थ है इसलिये बस मेरेको याद कर ले तो इसको मेरी प्राप्ति हो जायगी।''मामेव स्मरन्'' का तात्पर्य है कि सुनने समझने और माननेमें जो कुछ आता है वह सब मेरा समग्ररूप है। अतः जो उसको मेरा ही स्वरूप मानेगा उसको अन्तकालमें भी मेरा ही चिन्तन होगा अर्थात् उसने जब सब कुछ मेरा ही स्वरूप मान लिया तो अन्तकालमें उसको जो कुछ याद आयेगा वह मेरा ही स्वरूप होगा इसलिये वह स्मरण मेरा ही होगा। मेरा स्मरण होनेसे उसको मेरी ही प्राप्ति होगी।''मद्भावम्'' कहनेका तात्पर्य है कि साधकने मेरेको जिसकिसी भिन्न अथवा अभिन्न भावसे अर्थात् सगुणनिर्गुण साकारनिराकार द्विभुजचतुर्भुज तथा नाम लीला धाम रूप आदिसे स्वीकार किया है मेरी उपासना की है अन्तसमयके स्मरणके अनुसार वह मेरे उसी भावको प्राप्त होता है।
जो भगवान्की उपासना करते हैं वे तो अन्तसमयमें उपास्यका स्मरण होनेसे उसी उपास्यको अर्थात् भगवद्भावको प्राप्त होते हैं। परन्तु जो उपासना नहीं करते उनको भी अन्तसमयमें किसी कारणवशात् भगवान्के किसी नाम रूप लीला धाम आदिका स्मरण हो जाय तो वे भी उन उपासकोंकी तरह उसी भगवद्भावको प्राप्त हो जाते हैं। तात्पर्य है कि जैसे गुणोंमें स्थित रहनेवालेकी (गीता 14। 18) और अन्तकालमें जिसकिसी गुणके बढ़नेवालेकी वैसी ही गति होती है (गीता 14। 14 15) ऐसे ही जिसको अन्तमें भगवान् याद आ जाते हैं उसकी भी उपासकोंकी तरह गति होती है अर्थात् भगवान्की प्राप्ति होती है।भगवान्के सगुणनिर्गुण साकारनिराकार आदि अनेक रूपोंका और नाम लीला धाम आदिका भेद तो साधकोंकी दृष्टिसे है अन्तमें सब एक हो जाते हैं अर्थात् अन्तमें सब एक मद्भाव -- भगवद्भावको प्राप्त हो जाते हैं क्योंकि भगवान्का समग्र स्वरूप एक ही है। परन्तु गुणोंके अनुसार गतिको प्राप्त होनेवाले अन्तमें एक नहीं हो सकते क्योंकि तीनों गुण (सत्त्व रज तम) अलगअलग हैं। अतः गुणोंके अनुसार उनकी गतियाँ भी अलगअलग होती हैं।भगवान्का स्मरण करके शरीर छोड़नेवालोंका तो भगवान्के साथ सम्बन्ध रहता है और गुणोंके अनुसार शरीर छोड़नेवालोंका गुणोंके साथ सम्बन्ध रहता है। इसलिये अन्तमें भगवान्का स्मरण करनेवाले भगवान्के सम्मुख हो जाते हैं अर्थात् भगवान्को प्राप्त हो जाते हैं और गुणोंसे सम्बन्ध रखनेवाले गुणोंके सम्मुख हो जाते हैं अर्थात् गुणोंके कार्य जन्ममरणको प्राप्त हो जाते हैं।भगवान्ने एक यह विशेष छूट दी हुई है कि मरणासन्न व्यक्तिके कैसे ही आचरण रहे हों कैसे ही भाव रहे हों किसी भी तरहका जीवन बीता हो पर अन्तकालमें वह भगवान्को याद कर ले तो उसका कल्याण हो जायगा। कारण कि भगवान्ने जीवका कल्याण करनेके लिये ही उसको मनुष्यशरीर दिया है और जीवने उस मनुष्यशरीरको स्वीकार किया है। अतः जीवका कल्याण हो जाय तभी भगवान्का इस जीवको मनुष्यशरीर देना और जीवका मनुष्यशरीर लेना सफल होगा। परन्तु वह अपना उद्धार किये बिना ही आज दुनियासे विदा हो रहा है इसके लिये भगवान् कहते हैं कि भैया तेरी और मेरी दोनोंकी इज्जत रह जाय इसलिये अब जातेजाते (अन्तकालमें) भी तू मेरेको याद कर ले तो तेरा कल्याण हो जाय अतः हरेक मनुष्यके लिये सावधान होनेकी जरूरत है कि वह सब समयमें भगवान्का स्मरण करे कोई समय खाली न जाने दे क्योंकि अन्तकालका पता नहीं है कि कब आ जाय। वास्तवमें सब समय अन्तकाल ही है। यह बात तो है नहीं कि इतने वर्ष इतने महीने और इतने दिनोंके बाद मृत्यु होगी। देखनेमें तो यही आता है कि गर्भमें ही कई बालक मर जाते हैं कई जन्मते ही मर जाते हैं कई कुछ दिनोंमें महीनोंमें वर्षोंमें मर जाते हैं। इस प्रकार मरनेकी चाल हरदम चल ही रही है। अतः सब समयमें भगवान्को याद रखना चाहिये और यही समझना चाहिये कि बस यही अन्तकाल है नीतिमें यह बात आती है कि अगर धर्मका आचरण करना हो कल्याण करना हो तो मृत्युने मेरे केश पकड़े हुए हैं झटका दिया कि खत्म ऐसा विचार हरदम रहना चाहिये -- ''गृहीत इव केशेषु मृत्युना धर्ममाचरेत्''।
भगवान्की उपर्युक्त छूटसे मनुष्यमात्रको विशेष लाभ लेना चाहिये। कहीं कोई भी व्याधिग्रस्त मरणासन्न व्यक्ति हो तो उसके इष्टके चित्र या मूर्तिको उसे दिखाना चाहिये जैसी उसकी उपासना है और जिस भगवन्नाममें उसकी रुचि हो जिसका वह जप करता हो वही भगवन्नाम उसको सुनाना चाहिये जिस स्वरूपमें उसकी श्रद्धा और विश्वास हो उसकी याद दिलानी चाहिये भगवान्की महिमाका वर्णन करना चाहिये गीताके श्लोक सुनाने चाहिये। अगर वह बेहोश हो जाय तो उसके पास भगवन्नामका जपकीर्तन करना चाहिये जिससे उस मरणासन्न व्यक्तिके सामने भगवत्सम्बन्धी वायुमण्डल बना रहे। भगवत्सम्बन्धी वायुमण्डल रहनेसे वहाँ यमराजके दूत नहीं आ सकते। अजामिलके द्वारा मृत्युके समय नारायण नामका उच्चारण करनेसे,वहाँ भगवान्के पार्षद आ गये और यमदूत भागकर यमराजके पासमें गये तो यमराजने अपने दूतोंसे कहा कि जहाँ भगवन्नामका जप कीर्तन कथा आदि होते हों वहाँ तुमलोग कभी मत जाना क्योंकि वहाँ हमारा राज्य नहीं है (टिप्पणी प0 455.1)। ऐसा कहकर यमराजने भगवान्का स्मरण करके भगवान्से क्षमा माँगी कि मेरे दूतोंके द्वारा जो अपराध हुआ है उसको आप क्षमा करें (टिप्पणी प0 455.2)। अन्तकालमें स्मरणका तात्पर्य है कि उसने भगवान्का जो स्वरूप मान रखा है उसकी याद आ जाय अर्थात् उसने पहले राम कृष्ण विष्णु शिव शक्ति गणेश सूर्य सर्वव्यापक विश्वरूप परमात्मा आदिमेंसे जिस स्वरूपको मान रखा है उस स्वरूपके नाम रूप लीला धाम गुण प्रभाव आदिकी याद आ जाय। उसकी याद करते हुए शरीरको छोड़कर जानेसे वह भगवान्को ही प्राप्त होता है। कारण कि भगवान्की याद आनेसे मैं शरीर हूँ और शरीर मेरा है -- इसकी याद नहीं रहती प्रत्युत केवल भगवान्को ही याद करते हुए शरीर छूट जाता है। इसलिये उसके लिये भगवान्को प्राप्त होनेके अतिरिक्त और कोई गुंजाइश ही नहीं है।
यहाँ शङ्का होती है कि जिस व्यक्तिने उम्रभरमें भजनस्मरण नहीं किया कोई साधन नहीं किया सर्वथा भगवान्से विमुख रहा उसको अन्तकालमें भगवान्का स्मरण कैसे होगा और उसका कल्याण कैसे होगा इसका समाधान है कि अन्तसमयमें उसपर भगवान्की कोई विशेष कृपा हो जाय अथवा उसको किसी सन्तके दर्शन हो जायँ तो भगवान्का स्मरण होकर उसका कल्याण हो जाता है। उसके कल्याणके लिये कोई साधक उसको भगवान्का नाम लीला चरित्र सुनाये पद गाये तो भगवान्का स्मरण होनेसे उसका कल्याण हो जाता है। अगर मरणासन्न व्यक्तिको गीतामें रुचि हो तो उसको गीताका आठवाँ अध्याय सुनाना चाहिये क्योंकि इस अध्यायमें जीवकी सद्गतिका विशेषतासे वर्णन आया है। इसको सुननेसे उसको भगवान्की स्मृति हो जाती है। कारण कि वास्तवमें परमात्माका ही अंश होनेसे उसका परमात्माके साथ स्वतः सम्बन्ध है ही। अगर अयोध्या मथुरा हरिद्वार काशी आदि किसी तीर्थस्थलमें उसके प्राण छूट जायँ तो उस तीर्थके प्रभावसे उसको भगवान्की स्मृति हो जायगी (टिप्पणी प0 456.1)। ऐसे ही जिस जगह भगवान्के नामका जप कीर्तन कथा सत्संग आदि होता है उस जगह उसकी मृत्यु हो जाय तो वहाँके पवित्र वायुमण्डलके प्रभावसे उसको भगवान्की स्मृति हो सकती है। अन्तकालमें कोई भयंकर स्थिति आनेसे भयभीत होनेपर भी भगवान्की याद आ सकती है। शरीर छूटते समय शरीर कुटुम्ब रुपये आदिकी आशाममता छूट जाय और यह भाव हो जाय कि हे नाथ आपके बिना मेरा कोई नहीं है केवल आप ही मेरे हैं तो भगवान्की स्मृति होनेसे कल्याण हो जाता है। ऐसे ही किसी कारणसे अचानक अपने कल्याणका भाव बन जाय तो भी कल्याण हो सकता है (टिप्पणी प0 456.2)। ऐसे ही कोई साधक किसी प्राणी जीवजन्तुके मृत्युसमयमें उसका कल्याण हो जाय इस भावसे उसको भगवन्नाम सुनाता है तो उस भगवन्नामके प्रभावसे उस प्राणीका कल्याण हो जाता है। शास्त्रोंमें तो सन्तमहापुरुषोंके प्रभावकी विचित्र बातें आती हैं कि यदि सन्तमहापुरुष किसी मरणासन्न व्यक्तिको देख लें अथवा उसके मृत शरीर(मुर्दे) को देख लें अथवा उसकी चिताके धुएँको देख लें अथवा चिताकी भस्मको देख लें तो भी उस जीवका कल्याण हो जाता है (टिप्पणी प0 456.3)मार्मिक बातइस अध्यायके तीसरेचौथे श्लोकोंमें ब्रह्म अध्यात्म आदि जिन छः बातोंका वर्णन किया गया है उसका तात्पर्य समग्ररूपसे है और समग्ररूपका तात्पर्य है-- ''वासुदेवः सर्वम्'' अर्थात् सब कुछ वासुदेव ही है। जिसको समग्ररूपका ज्ञान हो गया है उसके लिये अन्तकालके स्मरणकी बात ही नहीं की जा सकती। कारण कि जिसकी दृष्टिमें संसारकी स्वतन्त्र सत्ता न होकर सब कुछ वासुदेव ही है उसके लिये अन्तकालमें भगवान्का चिन्तन करें यह कहना ही नहीं बनता। जैसे सामान्य मनुष्यको मैं हूँ इस अपने होनेपनका किञ्चिन्मात्र भी स्मरण नहीं करना पड़ता ऐसे ही उस महापुरुषको भगवान्का स्मरण नहीं करना पड़ता प्रत्युत उसको जाग्रत् स्वप्न सुषुप्ति आदि अवस्थाओंमें भगवान्के होनेपनका स्वाभाविक अटल ज्ञान,रहता है।पवित्रसेपवित्र अथवा अपवित्रसेअपवित्र किसी भी देशमें उत्तरायणदक्षिणायन शुक्लपक्षकृष्णपक्ष दिनरात्रि प्रातःसायं आदि किसी भी कालमें जाग्रत् स्वप्न सुषुप्ति मूर्च्छा रुग्णता नीरोगता आदि किसी भी अवस्थामें और पवित्र अथवा अपवित्र कोई भी वस्तु व्यक्ति पदार्थ आदि सामने होनेपर भी उस महापुरुषके कल्याणमें किञ्चिन्मात्र भी सन्देह नहीं रहता उपर्युक्त महापुरुषोंके सिवाय परमात्माकी उपासना करनेवाले जितने भी साधक हैं वे चाहे साकारके उपासक हों अथवा निराकारके उपासक हों चाहे सगुणके उपासक हों अथवा निर्गुणके उपासक हों चाहे राम कृष्ण आदि अवतारोंके उपासक हों भगवान्के किसी भी नाम रूप लीला धाम आदिकी श्रद्धाप्रेमपूर्वक उपासना करनेवाले क्यों न हों उन सबको अपनीअपनी रुचिके अनुसार अन्तसमयमें भगवान्के किसी भी स्वरूप नाम आदिका स्मरण हो जाय तो वह भगवान्का ही स्मरण है।साधकोंके सिवाय जिन मनुष्योंमें भगवान् हैं ऐसा सामान्य आस्तिकभाव है और वे किसी उपासनाविशेषमें नहीं लगे हैं उनको भी अन्तसमयमें कई कारणोंसे भगवान्का स्मरण हो सकता है। जैसे जीवनमें उसने सुना हुआ है कि दुःखीके दुःखको भगवान् मिटाते हैं इस संस्कारसे अन्तसमयकी पीड़ा(दुःख) के समय भगवान्की याद आ सकती है। अन्तसमयमें अगर यमदूत दिखायी दे जायँ तो भयके कारण भगवान्का स्मरण हो सकता है। कोई सज्जन उसके सामने भगवान्का चित्र रख दे -- उसको दिखा दे उसको भगवन्नाम सुना दे भगवान्की लीलाकथी सुना दे भक्तोंके चरित्र सुना दे उसके सामने कीर्तन करने लग जाय तो उसको भगवान्की याद आ जायगी। इस प्रकार किसी भी कारणसे भगवान्की तरफ वृत्ति होनेसे वह स्मरण भगवान्का ही स्मरण है।ऐसे साधक और सामान्य मनुष्योंके लिये ही अन्तकालमें भगवत्स्मरणकी बात कही जाती है तत्त्वज्ञ जीवन्मुक्त महापुरुषोंके लिये नहीं।
सम्बन्ध --अन्तकालमें जो मेरा स्मरण करते हैं वे तो मेरेको ही प्राप्त होते हैं पर जो मेरा स्मरण न करके अन्य कि'),
('swami-ramsukhdas-hc:source:8.5','Swami Ramsukhdas','gita.8.5','hi','commentary','सीका स्मरण करते हैं वे किसको प्राप्त होते हैं -- इसे भगवान् आगेके श्लोकमें बताते हैं।'),
('swami-ramsukhdas-hc:source:8.6','Swami Ramsukhdas','gita.8.6','hi','commentary','।।8.6।। व्याख्या--''यं यं वापि स्मरन्भावं ৷৷. सदा तद्भावभावितः''--भगवान्ने इस नियममें दयासे भरी हुई एक विलक्षण बात बतायी है कि अन्तिम चिन्तनके अनुसार मनुष्यको उसउस योनिकी प्राप्ति होती है जब यह नियम है तो मेरी स्मृतिसे मेरी प्राप्ति होगी ही परम दयालु भगवान्ने अपने लिये अलग कोई विशेष नियम नहीं बताया है प्रत्युत सामान्य नियममें ही अपनेको शामिल कर दिया है। भगवान्की दयाकी यह कितनी विलक्षणता है कि जितने मूल्यमें कुत्तेकी योनि मिले उतने ही मूल्यमें भगवान् मिल जायँ ''सदा तद्भावभावितः'' का तात्पर्य है कि अन्तकालमें जिस भावका -- जिस किसीका चिन्तन होता है शरीर छोड़नेके बाद वह जीव जबतक दूसरा शरीर धारण नहीं कर लेता तबतक वह उसी भावसे भावित रहता है अर्थात् अन्तकालका चिन्तन (स्मरण) वैसा ही स्थायी बना रहता है। अन्तकालके उस चिन्तनके अनुसार ही उसका मानसिक शरीर बनता है और मानसिक शरीरके अनुसार ही वह दूसरा शरीर धारण करता है। कारण कि अन्तकालके चिन्तनको बदलनेके लिये वहाँ कोई मौका नहीं है शक्ति नहीं है और बदलनेकी स्वतन्त्रता भी नहीं है तथा नया चिन्तन करनेका कोई अधिकार भी नहीं है। अतः वह उसी चिन्तनको लिये हुए उसीमें तल्लीन रहता है। फिर उसका जिस किसीके साथ कर्मोंका किञ्चिन्मात्र भी सम्बन्ध रहता है वायु जल खाद्यपदार्थ आदिके द्वारा वह वहीं पुरुषजातिमें प्रविष्ट होता है। फिर पुरुषजातिसे स्त्रीजातिमें जाकर समयपर जन्म लेता है। जैसे कुत्तेका पालन करनेवाला कोई मनुष्य अन्तसमयमें कुत्तेको याद करते,हुए शरीर छोड़ता है तो उसका मानसिक शरीर कुत्तेका बन जाता है जिससे वह क्रमशः कुत्ता ही बन जाता है अर्थात् कुत्तेकी योनिमें जन्म लेता है। इस तरह अन्तकालमें जिस किसीका स्मरण होता है उसीके अनुसार जन्म लेना पड़ता है। परन्तु इसका तात्पर्य यह नहीं है कि मकानको याद करते हुए शरीर छोड़नेसे मकान बन जायगा धनको याद करते हुए शरीर छोड़नेसे धन बन जायगा आदि। प्रत्युत मकानका चिन्तन होनेसे वह उस मकानमें चूहा छिपकली आदि बन जायगा और धनका चिन्तन होनेसे वह साँप बन जायगा आदि। तात्पर्य यह हुआ कि अन्तकालके चिन्तनका नियम सजीव प्राणियोंके लिये ही है निर्जीव (जड) पदार्थोंके लिये नहीं। अतः जड पदार्थका चिन्तन होनेसे वह उससे सम्बन्धित कोई सजीव प्राणी बन जायगा।मनुष्येतर (पशु पक्षी आदि) प्राणियोंको अपनेअपने कर्मोंके अनुसार ही अन्तकालमें स्मरण होता है और उसीके अनुसार उनका अगला जन्म होता है। इस तरह अन्तकालके स्मरणका कानून सब जगह लागू पड़ता है। परन्तु मनुष्यशरीरमें यह विशेषता है कि उसका अन्तकालका स्मरण कर्मोंके अधीन नहीं है प्रत्युत पुरुषार्थके अधीन है। पुरुषार्थमें मनुष्य सर्वथा स्वतन्त्र है। तभी तो अन्य योनियोंकी अपेक्षा इसकी अधिक महिमा है।मनुष्य इस शरीरमें स्वतन्त्रतापूर्वक जिससे सम्बन्ध जोड़ लेता है उस सम्बन्धके अनुसार ही उसका अन्य योनियोंमें जन्म हो सकता है। परन्तु अन्तकालमें अगर वह भगवान्का स्मरण कर ले तो उसके सारे सम्बन्ध टूट जाते हैं। कारण कि वे सब सम्बन्ध वास्तविक नहीं है प्रत्युत वर्तमानके बनाये हुए कृत्रिम हैं जब कि भगवान्के साथ सम्बन्ध स्वतःसिद्ध है बनाया हुआ नहीं है। अतः भगवान्की याद आनेसे उसके सारे कृत्रिम सम्बन्ध टूट जाते हैं।
विशेष बात
(1) दूसरे जन्मकी प्राप्ति अन्तकालमें हुए चिन्तनके अनुसार होती है। जिसका जैसा स्वभाव होता है अन्तकालमें उसे प्रायः वैसा ही चिन्तन होता है। जैसे जिसका कुत्ते पालनेका स्वभाव होता है अन्तकालमें उसे कुत्तेका चिन्तन होता है। वह चिन्तन आकाशवाणीकेन्द्रके द्वारा प्रसारित (विशेष शक्तियुक्त) ध्वनिकी तरह सब जगह फैल जाता है। जैसे आकाशवाणीकेन्द्रके द्वारा प्रसारित ध्वनि रेडियोके द्वारा (किसी विशेष नंबरपर) पकड़में आ जाती है। ऐसे ही अन्तकालीन कुत्तेका चिन्तन सम्बन्धित कुत्तेके द्वारा (जिसके साथ कोई ऋणानुबन्ध अथवा कर्मों आदिका कोईनकोई सम्बन्ध है) पकड़में आ जाता है। फिर जीव सूक्ष्म और कारणशरीरको साथ लिये अन्न जल वायु (श्वास) आदिके द्वारा उस कुत्तेमें प्रविष्ट हो जाता है। फिर कुतियामें प्रविष्ट होकर गर्भ बन जाता है और निश्चित समयपर कुत्तेके शऱीरसे जन्म लेता है।
अन्तकालीन चिन्तन और उसके अनुसार गतिको एक दृष्टान्तके द्वारा समझा जा सकता है। एक आदमी फोटो खिंचवाने गया। जब वह फोटो खिंचवाने बैठा तब फोटोग्राफरने उससे कहा कि फोटो खिंचते समय हिलना मत और मुस्कराते रहना। जैसे ही फोटो खिंचनेका समय आया उस आदमीकी नाकपर एक मक्खी बैठ गयी। हाथसे मक्खीको भगाना ठीक न समझकर (कि कहीं फोटोमें वैसा न आ जाय) उसने अपनी नाकको सिकोड़ा। ठीक इसी समय उसकी फोटो खिंच गयी। उस आदमीने फोटोग्राफरसे फोटो माँगी तो उसने कहा कि अभी फोटोको प्रत्यक्षरूपमें आनेमें कुछ समय लगेगा आप अमुक दिन फोटो ले जाना। वह दिन आनेपर फोटोग्राफरने उसे फोटो दिखायी तो उसमें (अपनी नाक सिकोड़े हुए) भद्दे रूपको देखकर वह आदमी बहुत नाराज हुआ कि तुमने फोटो बिगाड़ दी फोटोग्राफरने कहा कि इसमें मेरी क्या गलती है फोटो खिंचते समय आपने जैसी आकृति बनायी थी वैसी ही फोटोमें आ गयी अब तो फोटोमें परिवर्तन नहीं हो सकता। इसी तरह अन्तकालमें मनुष्यका जैसा चिन्तन होगा वैसी ही योनि उसको प्राप्त होगी।
फोटो खिंचनेका समय तो पहलेसे ही मालूम रहता है पर मृत्यु कब आ जाय -- इसका हमें कुछ पता नहीं रहता। इसलिये अपने स्वभाव चिन्तनको निर्मल बनाये रखते हुए हर समय सावधान रहना चाहिये और भगवान्का नित्यनिरन्तर स्मरण करते रहना चाहिये (गीता 8। 5 7)।
(2) अन्तकालीन गतिके नियममें भगवान्की न्यायकारिता और दयालुता -- ये दोनों ही भरी हुई हैं। साधारण दृष्टिसे न्याय और दया -- दोनों परस्परविरुद्ध मालूम देते हैं। अगर न्याय करेंगे तो दया सिद्ध नहीं होगी और दया करेंगे तो न्याय सिद्ध नहीं होगा। कारण कि न्यायमें ठीकठीक निर्णय होता है छूट नहीं होती और दयामें छूट होती है। परन्तु वास्तवमें यह विरोध सामान्य और क्रूर पुरुषके बनाये हुए न्यायमें ही आ सकता है भगवान्के बनाये हुए न्यायमें नहीं क्योंकि भगवान् परम दयालु और प्राणिमात्रके सुहृद् हैं --''सुहृदं सर्वभूतानाम्'' (गीता 5। 29)। भगवान्के सभी न्याय कानून दयासे परिपूर्ण होते हैं।मनुष्य अन्तकालमें जैसा स्मरण करता है उसीके अनुसार उसकी गति होती है। अगर कोई कुत्तेका चिन्तन करते हुए मरता है तो क्रमशः कुत्ता ही बन जाता है। यह भगवान्का मनुष्यमात्रके प्रति लागू होनेवाला न्याय हुआ क्योंकि भगवान्ने मनुष्यमात्रको यह स्वतन्त्रता दी है कि वह चाहे मेरा (भगवान्का) स्मरण करे चाहे अन्यका स्मरण करे। इसलिये यह भगवान्का न्याय है। जितने मूल्यमें कुत्तेकी योनि मिले उतने ही मूल्यमें भगवान् मिल जायँ -- यह मनुष्यमात्रके प्रति भगवान्की दया है। अगर मनुष्य भगवान्की इस न्यायकारिता और दयालुताकी तरफ खयाल करे तो उसका भगवान्में आकर्षण हो जायगा।
सम्बन्ध --जब अन्तकालके स्मरणके अनुसार ही गति होती है तो फिर अन्तकालमें भगवान्का स्मरण होनेके लिये मनुष्यको क्या करना चाहिये -- इसका उपाय आगेके श्लोकमें बताते हैं।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('swami-ramsukhdas-hc:source:8.7','Swami Ramsukhdas','gita.8.7','hi','commentary','।।8.7।। व्याख्या --''तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च''--यहाँ ''सर्वेषु कालेषु'' पदोंका सम्बन्ध केवल स्मरणसे ही है युद्धसे नहीं क्योंकि युद्ध सब समयमें निरन्तर हो ही नहीं सकता। कोई भी क्रिया निरन्तर नहीं हो सकती प्रत्युत समयसमयपर ही हो सकती है। कारण कि प्रत्येक क्रियाका आरम्भ और समाप्ति होती है -- यह बात सबके अनुभवकी है। परन्तु भगवत्प्राप्तिका उद्देश्य होनेसे भगवान्का स्मरण सब समयमें होता है क्योंकि उद्देश्यकी जागृति हरदम रहती है।सब समयमें स्मरण करनेके लिये कहनेका तात्पर्य है कि प्रत्येक कार्यमें समयका विभाग होता है जैसे -- यह समय सोनेका और यह समय जगनेका है यह समय नित्यकर्मका है यह समय जीविकाके लिये कामधंधा करनेका है यह समय भोजनका है आदिआदि। परन्तु भगवान्के स्मरणमें समयका विभाग नहीं होना चाहिये। भगवान्को तो सब समयमें ही याद रखना चाहिये।,''युध्य च'' कहनेका तात्पर्य है कि यहाँ अर्जुनके सामने युद्धरूप कर्तव्यकर्म है जो उनको स्वतः प्राप्त हुआ है -- ''यदृच्छया चोपपन्नम्'' (गीता 2। 32)। ऐसे ही मनुष्यको कर्तव्यरूपसे जो प्राप्त हो जाय उसको भगवान्का स्मरण करते हुए करना चाहिये। परन्तु उसमें भगवान्का स्मरण मुख्य है और कर्तव्यकर्म गौण है।
''अनुस्मर'' का अर्थ है कि स्मरणके पीछे स्मरण होता रहे अर्थात् निरन्तर स्मरण होता रहे। दूसरा अर्थ यह है कि भगवान् किसी भी जीवको भूलते नहीं। भगवान्ने सातवें अध्यायमें ''वेदाहम्'' (7। 26) कहकर वर्तमानमें सभी जीवोंको स्वतः जाननेकी बात कही है। जब भगवान् वर्तमानमें सबको जानते हैं तब भगवान्का सम्पूर्ण जीवोंका स्मरण करना स्वाभाविक हुआ अब यह जीव भगवान्का स्मरण करे तो इसका बेड़ा पार है भगवान्के स्मरणकी जागृतिके लिये भगवान्के साथ अपनापन होना चाहिये। यह अपनापन जितना ही दृढ़ होगा उतनी ही भगवान्की स्मृति बारबार आयेगी। ''मय्यर्पितमनोबुद्धिः''-- मेरेमें मनबुद्धि अर्पित कर देनेका साधारण अर्थ होता है कि मनसे भगवान्का चिन्तन हो और बुद्धिसे परमात्माका निश्चय किया जाय। परन्तु इसका वास्तविक अर्थ है -- मन बुद्धि इन्द्रियाँ शरीर आदिको भगवान्के ही मानना कभी भूलसे भी इनको अपने न मानना। कारण कि जितने भी प्राकृत पदार्थ हैं वे सबकेसब भगवान्के ही हैं। उन प्राकृत पदार्थोंको अपना मानना ही गलती है। साधक जबतक उनको अपना मानेगा तबतक वे शुद्ध नहीं हो सकते क्योंकि उनको अपना मानना ही खास अशुद्धि है और इस अशुद्धिसे ही अनेक अशुद्धियाँ पैदा होती हैं।वास्तवमें मनुष्यका सम्बन्ध केवल प्रभुके साथ ही है। प्रकृति और प्रकृतिके कार्यके साथ मनुष्यका सम्बन्ध कभी था नहीं है नहीं और रहेगा भी नहीं। कारण कि मनुष्य साक्षात् परमात्माके सनातन अंश हैं अतः उनका प्रकृतिसे सम्बन्ध कैसे हो सकता है इसलिये साधकको चाहिये कि वह मन और बुद्धिको भगवान्के ही समझकर भगवान्के अर्पण कर दे। फिर उसको स्वाभाविक ही भगवान्की प्राप्ति हो जायगी क्योंकि प्रकृतिके कार्य शरीर मन बुद्धि आदिके साथ सम्बन्ध जोड़नेसे ही वह भगवान्से विमुख हुआ था।वे प्राकृत पदार्थ कैसे हैं -- इस विषयमें दार्शनिक मतभेद तो है पर वे हमारे नहीं हैं और हम उनके नहीं हैं -- इस वास्तविकतामें कोई मतभेद नहीं है अर्थात् इसको सभी दर्शनकार मानते हैं। इन दर्शनकारोंमें जो ईश्वरवादी हैं वे सभी उन प्राकृत पदार्थोंको ईश्वरके ही मानते हैं और दूसरे जितने दर्शनकार हैं वे उन पदार्थोंको चाहे प्रकृतिके मानें चाहे परमात्माके मानें पर दार्शनिक दृष्टिसे वे उनको अपने नहीं मान सकते। अतः साधक उन सब पदार्थोंको ईश्वरके ही मानकर ईश्वरके अर्पण कर दें तो उनका हम भगवान्के ही थे और भगवान्के ही रहेंगे ऐसा भगवान्के साथ नित्यसम्बन्ध जाग्रत् हो जायगा। ''मामेवैष्यस्यसंशयम्'' -- मेरेमें मनबुद्धि अर्पण करनेवाला होनेसे तू मेरेको ही प्राप्त होगा -- इसमें कोई सन्देह नहीं है। कारण कि मैं तुझे नित्य प्राप्त हूँ। अप्राप्तिका अनुभव तो कभी प्राप्त न होनेवाले शरीर और संसारको अपना माननेसे उनके साथ सम्बन्ध जोड़नेसे ही होता है। नित्यप्राप्त तत्त्वका कभी अभाव नहीं हुआ और न हो सकता है। अगर तू मन बुद्धि और स्वयंको मेरे अर्पण कर देगा तो तेरा मेरे साथ जो नित्यसम्बन्ध है वह प्रकट हो जायगा -- इसमें कोई सन्देह नहीं है।
स्मरणसम्बन्धी विशेष बात
स्मरण तीन तरहका होता है -- बोधजन्य सम्बन्धजन्य और क्रियाजन्य। बोधजन्य स्मरणका कभी अभाव नहीं होता। जबतक सम्बन्धको न छोड़ें तबतक सम्बन्धजन्य स्मरण बना रहता है। क्रियाजन्य स्मरण निरन्तर नहीं रहता। इन तीनों प्रकारके स्मरणका विस्तार इस तरह है --
(1) बोधजन्य समरण-- अपना जो होनापन है उसको याद नहीं करना पड़ता। परन्तु शरीरके साथ जो एकता मान ली है वह भूल है। बोध होनेपर वह भूल मिट जाती है फिर अपना होनापन स्वतःसिद्ध रहता है। गीतामें भगवान्के वचन हैं -- तू मैं और ये राजा लोग पहले नहीं थे यह बात भी नहीं है और भविष्यमें नहीं रहेंगे यह बात भी नहीं है (गीता 2। 12) अर्थात् निश्चित ही पहले थे और निश्चित ही पीछे रहेंगे। जो पहले सर्गमहासर्ग और प्रलयमहाप्रलयमें था वही यह प्राणिसमुदाय उत्पन्न होहोकर नष्ट होता है (18। 19)। इसमें वही यह प्राणिसमुदाय तो परमात्माका अंश है और उत्पन्न होहोकर नष्ट होनेवाला शरीर है। अगर नष्ट होनेवाले भागका विवेकपूर्वक सर्वथा त्याग कर दें तो अपने होनेपनका स्पष्ट बोध हो,जाता है। यह बोधजन्य स्मरण नित्यनिरन्तर बना रहता है कभी नष्ट नहीं होता क्योंकि यह स्मरण अपने नित्य स्वरूपका है।
(2) सम्बन्धजन्य स्मरण-- जिसको हम स्वयं मान लेते हैं वह सम्बन्धजन्य स्मरण है जैसे शरीर हमारा है संसार हमारा है आदि। यह माना हुआ सम्बन्ध तबतक नहीं मिटता जबतक हम यह हमारा नहीं है ऐसा नहीं मान लेते। परन्तु भगवान् वास्तवमें हमारे हैं हम मानें तो हमारे हैं नहीं मानें तो हमारे हैं जानें तो हमारे हैं नहीं जानें तो हमारे हैं हमारे दीखें तो हमारे हैं हमारे नहीं दीखें तो हमारे हैं। हम सब उनके अंश हैं और वे अंशी हैं। हम उनसे अलग नहीं हो सकते और वे हमसे अलग नहीं हो सकते। जबतक हम शरीरसंसारके साथ अपना सम्बन्ध मानते हैं तबतक भगवान्का यह वास्तविक सम्बन्ध नष्ट नहीं होता। जब हम शरीर और संसारके सम्बन्धका अत्यन्त अभाव स्वीकार कर लेते हैं तब भगवान्का नित्यसम्बन्ध स्वतः जाग्रत् हो जाता है। फिर भगवान्का स्मरण नित्यनिरन्तर बना रहता है।
(3) क्रियाजन्य स्मरण-- क्रियाजन्य स्मरण अभ्यासजन्य होता है। जैसे स्त्रियाँ सिरपर जलका घड़ा रखकर चलती हैं तो अपने दोनों हाथोंको खुला रखती हैं और दूसरी स्त्रियोंके साथ बातें भी करती रहती हैं परन्तु सिरपर रखे घड़ेकी सावधानी निरन्तर रहती है। नट रस्सेपर चलते हुए गाता भी है बोलता भी है पर रस्सेका ध्यान निरन्तर रहता है। ड्राइवर मोटर चलाता है हाथसे गियर बदलता है हैण्डल घुमाता है और मालिकसे बातचीत भी करता है पर रास्तेका ध्यान निरन्तर रहता है। ऐसे ही सम्पूर्ण क्रियाओंमें भगवान्को निरन्तर याद रखना अभ्यासजन्य स्मरण है।
इस अभ्यासजन्य स्मरणके भी तीन प्रकार हैं -- (क) संसारका कार्य करते हुए भगवान्को याद रखना -- इसमें सांसारिक कार्यकी मुख्यता और भगवान्के स्मरणकी गौणता रहती है। अतः इसमें यह भाव रहता है कि संसारका काम बिगड़े नहीं ठीक तरहसे होता रहे और साथसाथ भगवान्का स्मरण भी होता रहे।
(ख) भगवान्को याद रखते हुए संसारका कार्य करना -- इसमें भगवान्के स्मरणकी मुख्यता और सांसारिक कार्यकी गौणता रहती है। इसमें भगवान्के स्मरणमें भूल न हो -- यह सावधानी रहती है और संसारके काममें भूल भी हो जाय तो उसकी परवाह नहीं होती। कारण कि साधकमें यह जागृति रहेगी कि संसारका काम सुधर जाय तो भी अन्तमें रहेगा नहीं और बिगड़ जाय तो भी अन्तमें रहेगा नहीं। इसलिये इसमें भगवान्के स्मरणकी भूल नहीं होती।
(ग) कार्यको भगवान्का ही समझना -- इसमें कामधंधा करते हुए भी एक विलक्षण आनन्द रहता है कि,मेरा अहोभाग्य है कि मैं भगवान्का ही काम करता हूँ भगवान्की ही सेवा करता हूँ अतः इसमें भगवान्की स्मृति विशेषतासे रहती है। जैसे कोई सज्जन अपनी कन्याके विवाहकार्यके समय कन्याके लिये तरहतरहकी वस्तुएँ खरीदता है तरहतरहके कार्य करता है अनेक व्यक्तियोंको निमन्त्रण देता है परन्तु अनेक प्रकारके कार्य करते हुए भी कन्याका विवाह करना है -- यह बात उसको निरन्तर याद रहती है। कन्यामें भगवान्के समान पूज्यभावपूर्वक सम्बन्ध नहीं होता तो भी उसके विवाहके लिये कार्य करते हुए उसकी याद निरन्तर रहती है फिर भगवान्के लिये कार्य करते हुए भगवान्की पूज्यभावसहित अपनेपनकी मीठी स्मृति निरन्तर बनी रहे -- इसमें कहना ही क्या है ,भगवत्सम्बन्धी कार्य दो तरहका होता है --
(1) स्वरूपसे-- भगवान्के नामका जप और कीर्तन करना भगवान्की लीलाका श्रवण चिन्तन पठनपाठन,आदि करना -- यह स्वरूपसे भगवत्सम्बन्धी काम है।
(2) भावसे--संसारका काम करते हुए भी जब सब संसार भगवान्का है तब संसारका काम भी भगवान्का ही काम हुआ। इसको भगवान्के नाते ही करना है भगवान्की प्रसन्नताके लिये ही करना है। इस कामसे हमें कुछ लेना नहीं है। भगवान्ने हमें जिस वर्णमें पैदा किया है जिस आश्रममें रखा है उसमें भगवान्की आज्ञाके अनुसार उचित काम करना है -- ऐसा भाव रहनेसे वह काम सांसारिक होनेपर भी भगवान्का हो जाता है।[सातवें अध्यायके अन्तमें भगवान्ने सात बातें कही थीं उन्हीं सात बातोंपर अर्जुनने आठवें अध्यायके आरम्भमें सात प्रश्न किये और यह प्रकरण भी सात ही श्लोकोंमें समाप्त हुआ।]
सम्बन्ध--पूर्वश्लोकमें कही हुई अभ्यासजन्य स्मृतिका अब आगेके श्लोकमें वर्णन करते हैं।'),
('swami-ramsukhdas-hc:source:8.8','Swami Ramsukhdas','gita.8.8','hi','commentary','।।8.8।। व्याख्या --[सातवें अध्यायके अट्ठाईसवें श्लोकमें जो सगुणनिराकार परमात्माका वर्णन हुआ था उसीको यहाँ आठवें नवें और दसवें श्लोकमें विस्तारसे कहा गया है।]
''अभ्यासयोगयुक्तेन''-- इस पदमें अभ्यास और योग -- ये दो शब्द आये हैं। संसारसे मन हटाकर परमात्मामें बारबार मन लगानेका नाम अभ्यास है और समताका नाम योग है-- ''समत्वं योग उच्यते'' (गीता 2। 48)। अभ्यासमें मन लगनेसे प्रसन्नता होती है और मन न लगनेसे खिन्नता होती है। यह अभ्यास तो है पर अभ्यासयोग नहीं है। अभ्यासयोग तभी होगा जब प्रसन्नता और खिन्नता -- दोनों ही न हों। अगर चित्तमें प्रसन्नता और खिन्नता हो भी जायँ तो भी उनको महत्त्व न दे केवल अपने लक्ष्यको ही महत्त्व दे। अपने लक्ष्यपर दृढ़ रहना भी योग है। ऐसे योगसे युक्त चित्त हो।''चेतसा नान्यगामिना'' -- चित्त अन्यगामी न हो अर्थात् एक परमात्माके सिवाय दूसरा कोई लक्ष्य न हो।''परमं पुरुषं दिव्यं याति पार्थानुचिन्तयन्''--ऐसे चित्तसे परम दिव्य पुरुषका अर्थात् सगुणनिराकार परमात्माका चिन्तन करते हुए शरीर छोड़नेवाला मनुष्य उसी परमात्माको प्राप्त हो जाता है।
सम्बन्ध --अब भगवान् ध्यान करनेके लिये अत्यन्त उपयोगी सगुणनिराकार परमात्माके स्वरूपका वर्णन करते हैं।'),
('swami-ramsukhdas-hc:source:8.9','Swami Ramsukhdas','gita.8.9','hi','commentary','।।8.9।। व्याख्या--''कविम्''-- सम्पूर्ण प्राणियोंको और उनके सम्पूर्ण शुभाशुभ कर्मोंको जाननेवाले होनेसे उन परमात्माका नाम ''कवि'' अर्थात् सर्वज्ञ है।''पुराणम्''--वे परमात्मा सबके आदि होनेसे ''पुराण'' कहे जाते हैं।''अनुशासितारम्''-- हम देखते हैं तो नेत्रोंसे देखते हैं। नेत्रोंके ऊपर मन शासन करता है, मनके ऊपर बुद्धि और बुद्धिके ऊपर ''अहम्'' शासन करता है तथा ''अहम्'' के ऊपर भी जो शासन करता है, जो सबका आश्रय, प्रकाशक और प्रेरक है, वह (परमात्मा) ''अनुशासिता'' है।दूसरा भाव यह है कि जीवोंका कर्म करनेका जैसा-जैसा स्वभाव बना है, उसके अनुसार ही परमात्मा (वेद, शास्त्र, गुरु, सन्त आदिके द्वारा) कर्तव्य-कर्म करनेकी आज्ञा देते हैं और मनुष्योंके पुराने पाप-पुण्यरूप,कर्मोंके अनुसार अनुकूल-प्रतिकूल परिस्थिति भेजकर उन मनुष्योंको शुद्ध, निर्मल बनाते हैं। इस प्रकार मनुष्योंके लिये कर्तव्य-अकर्तव्यका विधान करनेवाले और मनुष्योंके पाप-पुण्यरूप पुराने कर्मोंका (फल देकर) नाश करनेवाले होनेसे परमात्मा ''अनुशासिता'' है।''अणोरणीयांसम्''--परमात्मा परमाणुसे भी अत्यन्त सूक्ष्म हैं। तात्पर्य है कि परमात्मा मन-बुद्धिके विषय नहीं हैं; मन-बुद्धि आदि उनको पकड़ नहीं पाते। मन-बुद्धि तो प्रकृतिका कार्य होनेसे प्रकृतिको भी पकड़ नहीं पाते, फिर परमात्मा तो उस प्रकृतिसे भी अत्यन्त परे हैं! अतः वे परमात्मा सूक्ष्मसे भी अत्यन्त सूक्ष्म हैं अर्थात् सूक्ष्मताकी अन्तिम सीमा हैं। ''सर्वस्य धातारम्'' -- परमात्मा अनन्तकोटि ब्रह्माण्डोंको धारण करनेवाले हैं, उनका पोषण करनेवाले हैं। उन सभीको परमात्मासे ही सत्ता-स्फूर्ति मिलती है। अतः वे परमात्मा सबका धारण-पोषण करनेवाले कहे जाते हैं।''तमसः परस्तात्''--परमात्मा अज्ञानसे अत्यन्त परे हैं, अज्ञानसे सर्वथा रहित हैं। उनमें लेशमात्र भी अज्ञान नहीं है, प्रत्युत वे अज्ञानके भी प्रकाशक हैं।''आदित्यवर्णम्''--उन परमात्माका वर्ण सूर्यके समान है अर्थात् वे सूर्यके समान सबको मन-बुद्धि आदिको प्रकाशित करनेवाले हैं। उन्हींसे सबको प्रकाश मिलता है।''अचिन्त्यरूपम्''--उन परमात्माका स्वरूप अचिन्त्य है अर्थात् वे मन-बुद्धि आदिके चिन्तनका विषय नहीं हैं।''अनुस्मरेत्''--सर्वज्ञ, अनादि, सबके शासक, परमाणुसे भी अत्यन्त सूक्ष्म, सबका धारण-पोषण करनेवाले, अज्ञानसे अत्यन्त परे और सबको प्रकाशित करनेवाले सगुण-निराकार परमात्माके चिन्तनके लिये यहाँ ''अनुस्मरेत्'' पद आया है। यहाँ ''अनुस्मरेत्'' कहनेका तात्पर्य है कि प्राणिमात्र उन परमात्माकी जानकारीमें हैं; उनकी जानकारीके बाहर कुछ है ही नहीं अर्थात् उन परमात्माको सबका स्मरण है, अब उस स्मरणके बाद मनुष्य उन परमात्माको याद कर ले। यहाँ शङ्का होती है कि जो अचिन्त्य है, उसका स्मरण कैसे करें? इसका समाधान है कि ''वह परमात्मतत्त्व चिन्तनमें नहीं आता''--ऐसी दृढ़ धारणा ही अचिन्त्य परमात्माका चिन्तन है।
सम्बन्ध --अब अन्तकालके चिन्तनके अनुसार गति बताते हैं।'),
('swami-ramsukhdas-hc:source:8.10','Swami Ramsukhdas','gita.8.10','hi','commentary','।।8.10।। व्याख्या --प्रयाणकाले मनसाचलेन ৷৷. स तं परं पुरुषमुपैति दिव्यम्--यहाँ भक्ति नाम प्रियताका है; क्योंकि उस तत्त्वमें प्रियता (आकर्षण) होनेसे ही मन अचल होता है। वह भक्ति अर्थात् प्रियता स्वयंसे होती है, मन-बुद्धि आदिसे नहीं। अन्तकालमें कवि, पुराण, अनुशासिता आदि विशेषणोंसे (पीछेके श्लोकमें) कहे हुए सगुण-निराकार परमात्मामें भक्तियुक्त मनुष्यका मन स्थिर हो जाना अर्थात् सगुण-निराकार-स्वरूपमें आदरपूर्वक दृढ़ हो जाना ही मनका अचल होना है।पहले प्राणायामके द्वारा प्राणोंको रोकनेका जो अधिकार प्राप्त किया है, उसका नाम ''योगबल'' है। उस योगबलके द्वारा दोनों भ्रुवोंके मध्यभागमें स्थित जो द्विदल चक्र है, उसमें स्थित सुषुम्णा नाड़ीमें प्राणोंका,अच्छी तरहसे प्रवेश करके वह (शऱीर छोड़कर दसवें द्वारसे होकर) दिव्य परम पुरुषको प्राप्त हो जाता है।''तं परं पुरुषमुपैति दिव्यम्'' पदोंका तात्पर्य है कि जिस परमात्मतत्त्वका पीछेके (नवें) श्लोकमें वर्णन हुआ है, उसी दिव्य परम सगुण-निराकार परमात्माको वह प्राप्त हो जाता है।आठवें श्लोकमें जो बात कही गयी थी, उसीको नवें और दसवें श्लोकमें विस्तारसे कहकर इन तीन श्लोकोंके प्रकरणका उपसंहार किया गया है।इस प्रकरणमें सगुण-निराकार परमात्माकी उपासनाका वर्णन है। इस उपासनामें अभ्यासकी आवश्यकता है। प्राणायामपूर्वक मनको उस परमात्मामें लगानेका नाम अभ्यास है। यह अभ्यास अणिमा, महिमा आदि सिद्धि प्राप्त करनेके लिये नहीं है, प्रत्युत केवल परमात्मतत्त्वको प्राप्त करनेके लिये है। ऐसा अभ्यास करते हुए प्राणों और मनपर ऐसा अधिकार प्राप्त कर ले कि जब चाहे प्राणोंको रोक ले और मनको जब चाहे तभी तथा जहाँ चाहे वहीं लगा ले। जो ऐसा अधिकार प्राप्त कर लेता है, वही अन्तकालमें प्राणोंको सुषुम्णा नाड़ीमें प्रविष्ट कर सकता है। कारण कि जब अभ्यासकालमें भी मनको संसारसे हटाकर परमात्मामें लगानेमें साधकको कठिनताका, असमर्थताका अनुभव होता है तब अन्तकाल-जैसे कठिन समयमें मनको लगाना साधारण आदमीका काम नहीं है। जिसके पास पहलेसे योगबल है, वही अन्तसमयमें मनको परमात्मामें लगा सकता है और प्राणोंका सुषुम्णा नाड़ीमें प्रवेश करा सकता है।साधक पहले यह निश्चय कर ले कि अज्ञानसे अत्यन्त परे, सबसे अतीत जो परमात्मतत्त्व है, वह सबका प्रकाशक, सबका आधार और सबको सत्ता-स्फूर्ति देनेवाला निर्विकार तत्त्व है। उस तत्त्वमें ही प्रियता होनी चाहिये, मनका आकर्षण होना चाहिये, फिर उसमें स्वाभाविक मन लगेगा।
सम्बन्ध--अब भगवान् आगेके श्लोकमें निर्गुणनिराकारकी प्राप्तिके उपायका उपक्रम करते हैं।'),
('swami-ramsukhdas-hc:source:8.11','Swami Ramsukhdas','gita.8.11','hi','commentary','।।8.11।। व्याख्या--[सातवें अध्यायके उनतीसवें श्लोकमें जो निर्गुण-निराकार परमात्माका वर्णन हुआ था, उसीको यहाँ ग्यारहवें, बारहवें और तेरहवें श्लोकमें विस्तारसे कहा गया है।]''यदक्षरं वेदविदो वदन्ति''--वेदोंको जाननेवाले पुरुष जिसको अक्षर-निर्गुण-निराकार कहते हैं, जिसका कभी नाश नहीं होता, जो सदा-सर्वदा एकरूप, एकरस रहता है और जिसको इसी अध्यायके तीसरे श्लोकमें ''अक्षरं ब्रह्म परमम्'' कहा गया है, उसी निर्गुण-निराकार तत्त्वका यहाँ ''अक्षर'' नामसे वर्णन हुआ है।''विशन्ति यद्यतयो वीतरागाः''--जिनके अन्तःकरणमें रागका अत्यन्त अभाव हो गया है; अतः जिनका अन्तःकरण महान् निर्मल है और जिनके हृदयमें सर्वोपरि अद्वितीय परम तत्त्वको पानेकी उत्कट लगन लगी है, ऐसे प्रयत्नशील यति महापुरुष उस तत्त्वमें प्रवेश करते हैं--उसको प्राप्त करते हैं।''यदिच्छन्तो ब्रह्मचर्यं चरन्ति''--जिनका उद्देश्य केवल परमात्मतत्त्वकी प्राप्तिका है, परमात्मप्राप्तिके सिवाय जिनका और कोई ध्येय है ही नहीं और जो परमात्मप्राप्तिकी इच्छा रखकर ब्रह्मचर्यका पालन करते हैं, सम्पूर्ण इन्द्रियोंका संयम करते हैं अर्थात् किसी भी विषयका भोगबुद्धिसे सेवन नहीं करते।''तत्ते पदं संग्रहेण प्रवक्ष्ये''--जो सम्पूर्ण साधनोंका आखिरी फल है, उस पदको अर्थात् तत्त्वको मैं तेरे लिये संक्षेपसे और अच्छी तरहसे कहूँगा। संक्षेपसे कहनेका तात्पर्य है कि शास्त्रोंमें जिस तत्त्वको सर्वोपरि विलक्षण बताया गया है, हरेक आदमी उसको प्राप्त नहीं कर सकता--ऐसी जिसकी महिमा बतायी गयी है; वह पद (तत्त्व) किस तरहसे प्राप्त होता है-- इस बातको मैं कहूँगा। अच्छी तरहसे कहनेका तात्पर्य है कि ब्रह्मकी उपासना करनेवाले जिस तरहसे उस ब्रह्मको प्राप्त हो जाते हैं, उसको मैं अच्छी तरहसे कहूँगा।
सम्बन्ध --अन्तकालमें उस निर्गुण-निराकार तत्त्वकी प्राप्तिकी फलसहित विधि बतानेके लिये आगेके दो श्लोक कहते हैं।'),
('swami-ramsukhdas-hc:source:8.12','Swami Ramsukhdas','gita.8.12','hi','commentary','।।8.12।। व्याख्या--''सर्वद्वाराणि संयम्य''--(अन्तसमयमें) सम्पूर्ण इन्द्रियोंके द्वारोंका संयम कर ले अर्थात् शब्द, स्पर्श, रूप, रस और गन्ध-- इन पाँचों विषयोंसे श्रोत्र, त्वचा, नेत्र, रसना और नासिका-- इन पाँचों ज्ञानेन्द्रियोंको तथा बोलना, ग्रहण करना, गमन करना, मूत्र-त्याग और मल-त्याग-- इन पाँचों क्रियाओंसे वाणी, हाथ, चरण, उपस्थ और गुदा--इन पाँचों कर्मेन्द्रियोंको सर्वथा हटा ले। इससे इन्द्रियाँ अपने स्थानमें रहेंगी।''मनो हृदि निरुध्य च''--मनका हृदयमें ही निरोध कर ले अर्थात् मनको विषयोंकी तरफ न जाने दे। इससे मन अपने स्थान-(हृदय-) में रहेगा।''मूर्ध्न्याधायात्मनः प्राणम्''--प्राणोंको मस्तकमें धारण कर ले अर्थात् प्राणोंपर अपना अधिकार प्राप्त करके दसवें द्वार--ब्रह्मरन्ध्रमें प्राणोंको रोक ले।''आस्थितो योगधारणाम्''--इस प्रकार योगधारणामें स्थित हो जाय। इन्द्रियोंसे कुछ भी चेष्टा न करना, मनसे भी संकल्प-विकल्प न करना और प्राणोंपर पूरा अधिकार प्राप्त करना ही योगधारणामें स्थित होना है।
''ओमित्येकाक्षरं ब्रह्म व्याहरन्मामनुस्मरन्''-- इसके बाद एक अक्षर ब्रह्म ँ़ (प्रणव) का मानसिक उच्चारण करे और मेरा अर्थात् निर्गुण-निराकार परम अक्षर ब्रह्मका (जिसका वर्णन इसी अध्यायके तीसरे श्लोकमें हुआ है) स्मरण करे (टिप्पणी प0 464)। सब देश, काल, वस्तु, व्यक्ति, घटना, परिस्थिति आदिमें एक सच्चिदानन्दघन परमात्मा ही सत्तारूपसे परिपूर्ण हैं--ऐसी धारणा करना ही मेरा स्मरण है।''यः प्रयाति त्यजन्देहं स याति परमां गतिम्''--उपर्युक्त प्रकारसे निर्गुण-निराकारका स्मरण करते हुए जो देहका त्याग करता है अर्थात् दसवें द्वारसे प्राणोंको छोड़ता है वह परमगतिको अर्थात् निर्गुण-निराकार परमात्माको प्राप्त होता है।
सम्बन्ध--जिसके पास योगका बल होता है और जिसका प्राणोंपर अधिकार होता है, उसको तो निर्गुण-निराकारकी प्राप्ति हो जाती है; परन्तु दीर्घकालीन अभ्यास-साध्य होनेसे यह बात सबके लिये कठिन पड़ती है। इसलिये भगवान् आगेके श्लोकमें अपनी अर्थात् सगुण-साकारकी सुगमता-पूर्वक प्राप्तिकी बात कहते हैं।'),
